+	@PostMapping("/{accountNumber}/transactions")
+	public ResponseEntity<?> processTransaction(
+		@PathVariable String accountNumber,
+		@RequestBody(required = false) TransactionRequest request
+	) {
+		// Validate account number format
+		if (!ACCOUNT_NUMBER_PATTERN.matcher(accountNumber).matches()) {
+			return ResponseEntity.status(HttpStatus.BAD_REQUEST)
+				.body(new ErrorResponse("Account number must be an exact 10-digit identifier."));
+		}
+
+		if (request == null) {
+			return ResponseEntity.status(HttpStatus.BAD_REQUEST)
+				.body(new ErrorResponse("Request body is required."));
+		}
