+		String action = request.action();
+		if (action == null || action.isBlank()
+			|| (!action.equalsIgnoreCase("DEPOSIT") && !action.equalsIgnoreCase("WITHDRAW"))) {
+			return ResponseEntity.status(HttpStatus.BAD_REQUEST)
+				.body(new ErrorResponse("Invalid transaction type. Only DEPOSIT and WITHDRAW are supported."));
+		}
+
+		// Validate amount format before service call
